mapper.select:
	SELECT * FROM TB_EMPLOYEE_LOG


            AND EMPLOYEE_NO = #{dto.employee_no}


            AND ACTION_TYPE = #{dto.action_type}


            AND TARGET_TABLE = #{dto.target_table}


            AND RESPONSE_STATUS = #{dto.response_status}


            AND REQUEST_IP LIKE #{dto.request_ip} || '%'


            AND CREATED_AT >= #{dto.from_date}


            AND CREATED_AT < #{dto.to_date} + 1


	ORDER BY created_at DESC
